39: function buildTiles() {
40:   for (const cfg of CAMERAS) {
41:     const el = tpl.content.firstElementChild.cloneNode(true);
42:     el.querySelector(".name").textContent = cfg.name;
43:     const t = {
44:       cfg, el,
45:       video: el.querySelector("video"),
46:       select: el.querySelector(".device"),
47:       msg: el.querySelector(".msg"),
48:       stats: el.querySelector(".stats"),
49:       label: el.querySelector(".label"),
50:       stream: null, deviceId: null,
51:     };
52:     t.select.addEventListener("change", () => startTile(t, t.select.value));
53:     el.querySelector(".snap").addEventListener("click", () => snapshot(t));
54:     el.querySelector(".full").addEventListener("click", () => t.video.requestFullscreen?.());
55:     grid.appendChild(el);
56:     tiles[cfg.key] = t;
57:   }
58: }
