88: async function startTile(t, deviceId) {
89:   stopTile(t);
90:   t.deviceId = deviceId || null;
91:   t.msg.textContent = "";
92:   t.stats.textContent = "";
93:   if (!deviceId) {
94:     t.msg.textContent = `${t.cfg.name} not found. Is it plugged in?`;
95:     t.label.textContent = "";
96:     return;
97:   }
98:   const [w, h] = resSel.value.split("x").map(Number);
99:   const fps = Number(fpsSel.value);
100:   try {
101:     t.stream = await navigator.mediaDevices.getUserMedia({
102:       audio: false,
103:       video: {
104:         deviceId: { exact: deviceId },
105:         width: { ideal: w }, height: { ideal: h }, frameRate: { ideal: fps },
106:       },
107:     });
108:     t.video.srcObject = t.stream;
109:     const dev = devices.find((d) => d.deviceId === deviceId);
110:     t.label.textContent = dev?.label || deviceId;
111:   } catch (e) {
112:     t.msg.textContent = `Failed to open camera: ${e.name} — ${e.message}`;
113:   }
114: }
