125: async function startAll() {
126:   for (const t of Object.values(tiles)) fillSelect(t);
127:   // Open sequentially; opening several UVC cameras at once can fail on macOS.
128:   for (const t of Object.values(tiles)) await startTile(t, t.deviceId);
129:   const live = Object.values(tiles).filter((t) => t.stream).length;
130:   setStatus(`${live}/3 cameras live · FaceTime excluded`);
131: }
